   "type": "code",
   "data": {
    "filename": "ev_3.py",
    "headingEn": "main(): seven experiments",
    "headingKn": "main(): ಏಳು ಪ್ರಯೋಗಗಳು",
    "descEn": "main() builds a report, gates a good and a regressed candidate, feeds the gate empty and incomplete suites, runs it through a real subprocess exit code, compares candidates in pairs, measures small-suite noise and injects defects into the gate.",
    "descKn": "main() ವರದಿ ನಿರ್ಮಿಸಿ, ಒಳ್ಳೆಯ ಮತ್ತು ಹಿಂದೆ ಸರಿದ ಅಭ್ಯರ್ಥಿ gate ಮಾಡಿ, gate ಗೆ ಖಾಲಿ ಮತ್ತು ಅಪೂರ್ಣ suites ನೀಡಿ, ನಿಜ subprocess exit code ಮೂಲಕ ಓಡಿಸಿ, ಅಭ್ಯರ್ಥಿಗಳನ್ನು ಜೋಡಿಯಲ್ಲಿ ಹೋಲಿಸಿ, ಸಣ್ಣ-suite ಗದ್ದಲ ಅಳೆದು gate ಗೆ ದೋಷ ಸೇರಿಸುತ್ತದೆ.",
    "code": "def section(t):\n    print(f\"\\n--- {t} ---\")\n\n\ndef main():\n    N = {\"reasoning\": 40, \"tool_use\": 20, \"security\": 10, \"memory\": 10}\n    section(\"1. Genuinely computing: one suite report (seeded stand-in agent, assumed pass probabilities)\")\n    suite = make_suite(1, {\"reasoning\": 0.95, \"tool_use\": 0.97, \"security\": 1.0, \"memory\": 0.92}, N)\n    rep = build_report(suite)\n    print(rep)\n    print({k: round(v, 3) for k, v in category_rates(suite).items()})\n    print(\"first-pass success, repair rate and mean attempts come from the same results as the pass rate; two systems with the same final pass rate can differ a lot on these\")\n\n    section(\"2. Genuinely checking: gate decisions for a good candidate, a security regression and a critical failure\")\n    for label, probs in ((\"good candidate\", {\"reasoning\": 0.97, \"tool_use\": 0.99, \"security\": 1.0, \"memory\": 0.95}), (\"security regressed\", {\"reasoning\": 0.99, \"tool_use\": 1.0, \"security\": 0.7, \"memory\": 0.99})):\n        s = make_suite(2, probs, N)\n        r = build_report(s)\n        status, reasons = gate(s, baseline_rate=0.94)\n        print(f\"{label:20} overall {r.pass_rate:.1%}  gate={status} {reasons}\")\n    print(\"a candidate can have an overall rate that looks fine and still be blocked by the security gate and by its critical failures; averages are a summary, the gate is the decision\")\n\n    section(\"3. Genuinely checking: an empty or incomplete suite must not look like success\")\n    print(\"empty suite:\", gate([], 0.9))\n    partial = [r for r in make_suite(2, {\"reasoning\": 1.0, \"tool_use\": 1.0, \"security\": 1.0, \"memory\": 1.0}, N) if r.category != \"security\"]\n    print(\"security cases missing:\", gate(partial, 0.9))\n    thin = [r for r in make_suite(2, {\"reasoning\": 1.0, \"tool_use\": 1.0, \"security\": 1.0, \"memory\": 1.0}, N) if r.category != \"security\"] + make_suite(9, {\"security\": 1.0}, {\"security\": 1})\n    print(\"security collapsed to 1 case:\", gate(thin, 0.9))\n    print(\"each of these has no failing case, so a gate that only looks at failures would pass them; ERROR is a separate status that blocks because the evidence itself cannot be trusted\")\n\n    section(\"4. Genuinely checking: the gate as a real process exit code\")\n    code = (\n        \"import json,sys;d=json.loads(sys.argv[1]);print(json.dumps(d,sort_keys=True));sys.exit(0 if d['status']=='PASS' else 1 if d['status']=='FAIL' else 2)\"\n    )\n    good = make_suite(2, {\"reasoning\": 0.99, \"tool_use\": 1.0, \"security\": 1.0, \"memory\": 1.0}, N)\n    for label, s in ((\"good\", good), (\"empty\", [])):\n        status, reasons = gate(s, 0.94)\n        p = subprocess.run([sys.executable, \"-c\", code, json.dumps({\"status\": status, \"reasons\": reasons})], capture_output=True, text=True)\n        print(f\"{label:6} printed {p.stdout.strip()[:90]} exit code {p.returncode}\")\n    print(\"0 means pass, 1 means the candidate failed policy and 2 means the evidence could not be used; CI acts on the exit code, so printing FAIL and exiting 0 would have let a bad build through\")\n\n    section(\"5. Genuinely measuring: paired comparison of two candidates on the same 100 cases (assumed pass probabilities, seed 4)\")\n    rng = random.Random(4)\n    both = only_a = only_b = neither = 0\n    for _ in range(100):\n        a, b = rng.random() < 0.70, rng.random() < 0.85\n        both += a and b; only_a += a and not b; only_b += b and not a; neither += not a and not b\n    print(f\"both pass {both}, only prompt-only passes {only_a}, only workbench passes {only_b}, neither {neither}; rates {both + only_a}% and {both + only_b}%\")\n    print(\"the paired table shows where the two candidates disagree, which two success percentages hide; with 100 cases the difference between rates still has noticeable uncertainty, and prompt-only wins are reported where they occur\")\n\n    section(\"6. Genuinely measuring: noise in a pass rate from a small suite (true rate ASSUMED at 0.92, seed 6)\")\n    rng = random.Random(6)\n    for n in (20, 100, 1000):\n        rates = sorted(sum(rng.random() < 0.92 for _ in range(n)) / n for _ in range(2000))\n        print(f\"{n:5} cases: observed pass rate ranged from {rates[50]:.1%} to {rates[1949]:.1%} across 95 percent of reruns with no real change\")\n    print(\"a 20-case suite can swing by more than the 1-point regression tolerance with nothing changing, so a tight tolerance needs either many cases or repeated runs\")\n\n    section(\"7. Genuinely checking: failure injection into the gate itself\")\n    def broken_gate(rs):\n        return \"PASS\" if all(r.passed for r in rs) else \"FAIL\"  # forgets the empty and missing-evidence cases\n    print(\"broken gate on an empty suite:\", broken_gate([]), \"| real gate:\", gate([], 0.9)[0])\n    print(\"broken gate on a suite with only passing normal cases and no security category:\", broken_gate(partial), \"| real gate:\", gate(partial, 0.9)[0])\n    print(\"the defective gate behaves correctly whenever a case fails and only goes wrong when evidence is empty or missing, so ordinary failing-case tests would never find it; injecting the empty and missing-category inputs is how the defect is found\")"
   }
